import 'dart:convert';import 'dart:io';import 'package:http/http.dart' as http;import 'package:path/path.dart' as path;class SlackService {  final String botToken;  final String channel;  SlackService({    required this.botToken,    required this.channel,  });  /// Test the Slack connection  Future<bool> testConnection() async {    try {      final url = Uri.parse('https://slack.com/api/auth.test');      final response = await http.post(        url,        headers: {          'Authorization': 'Bearer $botToken',          'Content-Type': 'application/json',        },      );      if (response.statusCode == 200) {        final data = jsonDecode(response.body);        return data['ok'] as bool? ?? false;      }      return false;    } catch (e) {      return false;    }  }  /// Send a simple text message to Slack  Future<void> sendMessage(String message, {String? emoji}) async {    final url = Uri.parse('https://slack.com/api/chat.postMessage');    final response = await http.post(      url,      headers: {        'Authorization': 'Bearer $botToken',        'Content-Type': 'application/json',      },      body: jsonEncode({        'channel': channel,        'text': message,        if (emoji != null) 'icon_emoji': emoji,      }),    );    if (response.statusCode != 200) {      print('Failed to send Slack message: ${response.body}');    }  }  /// Send a rich message with attachments/blocks  Future<void> sendRichMessage({    required String title,    required String message,    String color = 'good', // good, warning, danger, or hex color    Map<String, String>? fields,    String? emoji,  }) async {    final url = Uri.parse('https://slack.com/api/chat.postMessage');    final attachment = {      'color': color,      'title': title,      'text': message,      'ts': DateTime.now().millisecondsSinceEpoch ~/ 1000,    };    if (fields != null && fields.isNotEmpty) {      attachment['fields'] = fields.entries          .map((e) => {                'title': e.key,                'value': e.value,                'short': true,              })          .toList();    }    final response = await http.post(      url,      headers: {        'Authorization': 'Bearer $botToken',        'Content-Type': 'application/json',      },      body: jsonEncode({        'channel': channel,        'attachments': [attachment],        if (emoji != null) 'icon_emoji': emoji,      }),    );    if (response.statusCode != 200) {      print('Failed to send rich Slack message: ${response.body}');    }  }  /// Upload a file to Slack  Future<void> uploadFile({    required File file,    String? title,    String? comment,  }) async {    final url = Uri.parse('https://slack.com/api/files.upload');    final request = http.MultipartRequest('POST', url);    request.headers['Authorization'] = 'Bearer $botToken';    // Add the file    request.files.add(await http.MultipartFile.fromPath(      'file',      file.path,      filename: path.basename(file.path),    ));    // Add other fields    request.fields['channels'] = channel;    if (title != null) request.fields['title'] = title;    if (comment != null) request.fields['initial_comment'] = comment;    final response = await request.send();    final responseBody = await response.stream.bytesToString();    if (response.statusCode != 200) {      print('Failed to upload file to Slack: $responseBody');    } else {      print('✅ File uploaded to Slack successfully');    }  }  /// Send build step notification  Future<void> sendBuildStepNotification({    required String step,    required String client,    required String platform,    required String status, // started, completed, failed    String? additionalInfo,    String? errorMessage,  }) async {    String emoji;    String color;    String message;    switch (status.toLowerCase()) {      case 'started':        emoji = ':rocket:';        color = '#36a64f'; // green        message = 'Build step started';        break;      case 'completed':        emoji = ':white_check_mark:';        color = 'good';        message = 'Build step completed successfully';        break;      case 'failed':        emoji = ':x:';        color = 'danger';        message = 'Build step failed';        break;      default:        emoji = ':information_source:';        color = 'warning';        message = 'Build step update';    }    final fields = <String, String>{      'Client': client,      'Platform': platform,      'Step': step,      'Status': status.toUpperCase(),    };    if (additionalInfo != null) {      fields['Info'] = additionalInfo;    }    if (errorMessage != null) {      fields['Error'] = errorMessage;    }    await sendRichMessage(      title: '$emoji Build Update - $step',      message: message,      color: color,      fields: fields,    );  }  /// Send build completion summary  Future<void> sendBuildSummary({    required String client,    required String platform,    required String type,    required String version,    required bool success,    required Duration buildTime,    String? errorMessage,    File? artifactFile,  }) async {    final emoji = success ? ':tada:' : ':rotating_light:';    final color = success ? 'good' : 'danger';    final title = success ? '$emoji Build Completed Successfully!' : '$emoji Build Failed!';    final fields = <String, String>{      'Client': client,      'Platform': platform,      'Type': type.toUpperCase(),      'Version': version,      'Build Time': '${buildTime.inMinutes}m ${buildTime.inSeconds % 60}s',      'Status': success ? 'SUCCESS' : 'FAILED',    };    if (errorMessage != null) {      fields['Error'] = errorMessage;    }    await sendRichMessage(      title: title,      message: success          ? 'Build completed successfully and is ready for distribution!'          : 'Build failed. Please check the logs for more details.',      color: color,      fields: fields,    );    // Upload artifact if it's an APK and build was successful    if (success && type.toLowerCase() == 'apk' && artifactFile != null) {      await uploadFile(        file: artifactFile,        title: '📱 ${client}_$version.apk',        comment: 'Fresh build ready for testing! 🚀\n\n'            '• Client: $client\n'            '• Version: $version\n'            '• Platform: $platform\n'            '• Build time: ${buildTime.inMinutes}m ${buildTime.inSeconds % 60}s',      );    }  }}